import numpy as np, itertools
lines=open('init.xyz').read().split('\n')
n=int(lines[0]); atoms=[l.split() for l in lines[2:2+n]]
els=[a[0] for a in atoms]; X=np.array([[float(v) for v in a[1:4]] for a in atoms])
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Ti':1.6}
def bonded(i,j):
    return np.linalg.norm(X[i]-X[j]) < cov[els[i]]+cov[els[j]]+0.4
bonds=[(i,j) for i,j in itertools.combinations(range(n),2) if bonded(i,j)]
bs=set(bonds)
allidx=set(range(n))
def rot_about(p, axis, ang):
    axis=axis/np.linalg.norm(axis)
    return p*np.cos(ang)+np.cross(axis,p)*np.sin(ang)+axis*(axis@p)*(1-np.cos(ang))
rotors={
 'Me1': (36,[38,39,40]),
 'Me2': (37,[41,42,43]),
 'CaH2': (30,[44,45]),
 'CcH2': (33,[46,47]),
}
def mindist(moved, others):
    m=1e9
    for i in moved:
        for j in others:
            if (min(i,j),max(i,j)) in bs: continue
            m=min(m,np.linalg.norm(X[i]-X[j]))
    return m
for it in range(3):
    for name,(anchor,hs) in rotors.items():
        nb=[j for j in range(n) if (min(anchor,j),max(anchor,j)) in bs and els[j]!='H' and j not in hs]
        axis=X[nb[0]]-X[anchor]
        others=sorted(allidx-set(hs)-{anchor})
        best=None
        for ang in np.arange(0,360,5):
            old=X[hs].copy()
            for li,h in enumerate(hs):
                X[h]=X[anchor]+rot_about(old[li]-X[anchor],axis,np.radians(ang))
