            for li,h in enumerate(hs):
                X[h]=old[li]
            if best is None or m>best[0]: best=(m,ang)
        old=X[hs].copy()
        for li,h in enumerate(hs):
            X[h]=X[anchor]+rot_about(old[li]-X[anchor],axis,np.radians(best[1]))
        print(name,'best min',round(best[0],2),'ang',best[1])
worst=[]
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bs: continue
    d=np.linalg.norm(X[i]-X[j])
    lim=1.9 if 'H' in (els[i],els[j]) else 2.3
    if d<lim: worst.append((round(d,2),i,els[i],j,els[j]))
worst.sort()
print(worst[:10])
with open('init2.xyz','w') as f:
    f.write(f"{n}\nTi ansa-amido tris(cyclopentadienyl) cation initial\n")
    for el,p in zip(els,X):
        f.write(f"{el} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
